const raw = $input.first().json || {};
const odataId = raw['@odata.id'] || '';
const messageId = raw.id || raw.messageId || '';
let chatId = raw.chatId || raw.chat?.id || raw.channelData?.chatId || raw.conversationId || raw.conversation?.id || '';
if (!chatId && odataId) {
  const direct = odataId.match(/\/chats\/([^\/]+)\/messages\/[^\/]+$/i);
  const quoted = odataId.match(/chats\('([^']+)'\)/i);
  chatId = direct?.[1] || quoted?.[1] || '';
}
const graphBase = 'https://graph.microsoft.com/v1.0';
return [{
  json: {
    receivedAt: new Date().toISOString(),
    trigger: raw,
    chatId,
    messageId,
    canLoadMessage: Boolean(chatId && messageId),
    urls: {
      chat: chatId ? `${graphBase}/chats/${encodeURIComponent(chatId)}` : '',
      message: chatId && messageId ? `${graphBase}/chats/${encodeURIComponent(chatId)}/messages/${encodeURIComponent(messageId)}` : '',
      hostedContents: chatId && messageId ? `${graphBase}/chats/${encodeURIComponent(chatId)}/messages/${encodeURIComponent(messageId)}/hostedContents` : ''
    }
  }
}];

const item = $input.first().json || {};
const values = Array.isArray(item.value) ? item.value : [];
const hostedContents = values.map((entry, index) => {
  const contentType = entry.contentType || '';
  const contentBytes = entry.contentBytes || '';
  let textPreview = '';
  if (contentBytes && /^(text\/|application\/(json|xml))/i.test(contentType)) {
    try { textPreview = Buffer.from(contentBytes, 'base64').toString('utf8').slice(0, 4000); } catch (error) { textPreview = ''; }
  }
  return { index, id: entry.id || '', contentType, isImage: /^image\//i.test(contentType), isTextLike: Boolean(textPreview), textPreview };
});
return [{ json: { hostedContents, hostedContentLoadError: item.error || null } }];

const item = $input.first().json || {};

const ownUserIds = [
  // TODO after import: add bot/service user ids, for example '00000000-0000-0000-0000-000000000000'
];
const agentDisplayNameHints = ['rwg assistent', 'rwg agent'];

function htmlToText(html) {
  return String(html || '')
    .replace(/<at[^>]*>.*?<\/at>/gi, ' ')
    .replace(/<attachment[^>]*><\/attachment>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(div|p|li)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function detectLanguage(text) {
  const lower = String(text || '').toLowerCase();
  const scores = {
    de: ['hallo', 'guten', 'bitte', 'danke', 'fehler', 'hilfe', 'kannst', 'was', 'wie', 'warum', 'ticket'],
    en: ['hello', 'please', 'thanks', 'error', 'help', 'can you', 'what', 'how', 'why', 'ticket'],
    nl: ['hallo', 'goedemorgen', 'alsjeblieft', 'dank', 'fout', 'hulp', 'waarom', 'hoe'],
    fr: ['bonjour', 'merci', 'erreur', 'aide', 'comment', 'pourquoi', 'pouvez'],
    es: ['hola', 'gracias', 'error', 'ayuda', 'como', 'por que', 'puedes'],
    it: ['ciao', 'grazie', 'errore', 'aiuto', 'come', 'perche', 'puoi']
  };
  let best = { code: 'de', score: 0 };
  for (const [code, words] of Object.entries(scores)) {
    const score = words.reduce((sum, word) => sum + (lower.includes(word) ? 1 : 0), 0);
    if (score > best.score) best = { code, score };
  }
  const labels = { de: 'Deutsch', en: 'English', nl: 'Nederlands', fr: 'Francais', es: 'Espanol', it: 'Italiano' };
  return { code: best.code, label: labels[best.code] || 'Deutsch', confidence: best.score > 0 ? 'heuristic' : 'default' };
}

function firstName(displayName) {
  const parts = String(displayName || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return '';
  return parts.length === 1 ? parts[0] : parts[parts.length - 1];
}

function salutation(language, name) {
  const prefix = { de: 'Hallo', en: 'Hello', nl: 'Hallo', fr: 'Bonjour', es: 'Hola', it: 'Ciao' }[language] || 'Hallo';
  return name ? `${prefix} ${name}` : prefix;
}

function quickAck(language) {
  return {
    de: 'Ich schaue mir das kurz an und melde mich gleich mit einer Antwort.',
    en: 'I am checking this and will come back with an answer shortly.',
    nl: 'Ik kijk er kort naar en kom zo met een antwoord terug.',
    fr: 'Je regarde cela et je reviens rapidement avec une reponse.',
    es: 'Lo reviso y vuelvo enseguida con una respuesta.',
    it: 'Controllo subito e torno a breve con una risposta.'
  }[language] || 'Ich schaue mir das kurz an und melde mich gleich mit einer Antwort.';
}

function fallback(language) {
  return {
    de: 'Ich konnte die Anfrage gerade nicht vollstaendig verarbeiten. Bitte versuche es gleich erneut oder formuliere die Frage etwas konkreter.',
    en: 'I could not process the request completely right now. Please try again shortly or make the question a bit more specific.',
    nl: 'Ik kon de vraag nu niet volledig verwerken. Probeer het zo opnieuw of formuleer de vraag iets specifieker.',
    fr: 'Je n ai pas pu traiter completement la demande pour le moment. Merci de reessayer ou de preciser la question.',
    es: 'No pude procesar la solicitud completamente ahora. Intentalo de nuevo o formula la pregunta con mas detalle.',
    it: 'Non sono riuscito a elaborare completamente la richiesta. Riprova tra poco o formula la domanda in modo piu preciso.'
  }[language] || 'Ich konnte die Anfrage gerade nicht vollstaendig verarbeiten. Bitte versuche es gleich erneut oder formuliere die Frage etwas konkreter.';
}

const chatMeta = item.chatMeta || {};
const messageMeta = item.messageMeta || {};
const rawBody = messageMeta.body || {};
const text = htmlToText(rawBody.content || '');
const language = detectLanguage(text);
const fromUser = messageMeta.from?.user?.displayName || messageMeta.from?.application?.displayName || '';
const fromUserId = messageMeta.from?.user?.id || messageMeta.from?.application?.id || '';
const fromType = messageMeta.from?.user ? 'user' : messageMeta.from?.application ? 'application' : 'unknown';
const chatId = messageMeta.chatId || chatMeta.id || item.chatId || '';
const messageId = messageMeta.id || item.messageId || '';
const lower = text.toLowerCase();
const isGreeting = /^(hallo|hi|hey|moin|servus|guten morgen|guten tag|guten abend|hello|good morning|bonjour|hola|ciao)\b/i.test(text) && text.length <= 40;
const intent = isGreeting ? 'greeting' : text.includes('?') ? 'question' : /fehler|error|problem|hilfe|help|störung|issue|bug/i.test(text) ? 'problem' : 'request';
const attachments = (messageMeta.attachments || []).map((a, index) => {
  const contentType = a.contentType || '';
  const contentUrl = a.contentUrl || '';
  const name = a.name || a.id || `attachment-${index + 1}`;
  return {
    index,
    id: a.id || '',
    name,
    contentType,
    contentUrl,
    hasUrl: Boolean(contentUrl),
    isImage: /^image\//i.test(contentType) || /\.(png|jpg|jpeg|gif|webp)$/i.test(name),
    isDocument: /pdf|word|excel|powerpoint|officedocument|msword|spreadsheet|presentation/i.test(contentType) || /\.(pdf|docx?|xlsx?|pptx?)$/i.test(name),
    rawContentPreview: typeof a.content === 'string' ? a.content.slice(0, 2000) : ''
  };
});
const links = Array.from(new Set((text.match(/https?:\/\/\S+/gi) || []).map(url => url.replace(/[).,;]+$/, ''))));
const hostedContents = Array.isArray(item.hostedContents) ? item.hostedContents : [];
const hasReadableAttachmentContext = attachments.some(a => a.rawContentPreview) || hostedContents.some(h => h.textPreview);
const isOwnMessage = ownUserIds.includes(fromUserId) || agentDisplayNameHints.some(name => fromUser.toLowerCase().includes(name));
const isOneOnOneChat = (chatMeta.chatType || '') === 'oneOnOne';
const shouldProcess = Boolean(isOneOnOneChat && fromType === 'user' && !isOwnMessage && chatId && messageId && (text || attachments.length || hostedContents.length));

return [{ json: {
  receivedAt: item.receivedAt || new Date().toISOString(),
  chat: { id: chatId, type: chatMeta.chatType || '', topic: chatMeta.topic || '', webUrl: chatMeta.webUrl || '', isOneOnOneChat },
  teams: { chatId, messageId, fromUser, fromUserId, fromType, firstName: firstName(fromUser), salutation: salutation(language.code, firstName(fromUser)), createdDateTime: messageMeta.createdDateTime || '' },
  body: { contentType: rawBody.contentType || '', rawHtml: rawBody.content || '', text, textLower: lower },
  language,
  attachments,
  hostedContents,
  links,
  control: { shouldProcess, isOwnMessage, isGreeting, intent, needsQuickAck: shouldProcess && !isGreeting },
  reliability: { chatLoadError: item.chatLoadError || null, messageLoadError: item.messageLoadError || null, hostedContentLoadError: item.hostedContentLoadError || null, hasReadableAttachmentContext },
  replies: { quickAck: quickAck(language.code), fallback: fallback(language.code) }
} }];

const item = $input.first().json;
const canLookupProfile = Boolean(item.teams?.fromUserId && item.teams?.fromType === 'user');
return [{ json: { ...item, senderLookup: { userId: item.teams?.fromUserId || '', displayName: item.teams?.fromUser || '', canLookupProfile } } }];

const original = $('Prepare Sender Lookup').first().json;
const p = $input.first().json || {};
return [{ json: { ...original, senderProfile: { id: p.id || original.senderLookup.userId || '', displayName: p.displayName || original.senderLookup.displayName || '', givenName: p.givenName || '', surname: p.surname || '', jobTitle: p.jobTitle || '', department: p.department || '', officeLocation: p.officeLocation || '', mail: p.mail || '', userPrincipalName: p.userPrincipalName || '' }, senderProfileFallback: Boolean(p.error) } }];

const item = $input.first().json;
const attachmentLines = (item.attachments || []).map(a => `- ${a.name || a.id}: type=${a.contentType || 'unknown'}, url=${a.contentUrl || 'none'}, image=${a.isImage}, document=${a.isDocument}, preview=${a.rawContentPreview || 'none'}`).join('
') || '- none';
const hostedLines = (item.hostedContents || []).map(h => `- id=${h.id || h.index}, type=${h.contentType || 'unknown'}, image=${h.isImage}, textPreview=${h.textPreview || 'none'}`).join('
') || '- none';
const linkLines = (item.links || []).map(url => `- ${url}`).join('
') || '- none';
const profile = item.senderProfile || {};
const systemMessage = `Du bist der RWG Assistent, ein interner Microsoft Teams AI-Agent fuer IT-, Prozess-, Jira- und Wissensfragen.

Antworte in der Sprache des Nutzers: ${item.language?.label || 'Deutsch'}.
Nutze zuerst interne Wissensquellen fuer interne Fachfragen. Nutze Jira nur bei konkreten Ticket-Keys. Nutze oeffentliche Webseiten nur fuer oeffentliche Informationen.
Erfinde nichts. Wenn Informationen fehlen, sage kurz was fehlt. Wenn die Anfrage unklar ist, stelle genau eine kurze Rueckfrage.
Wenn Attachments, Bilder, Dokumente oder Links im Kontext vorhanden sind, beruecksichtige sie sichtbar. Wenn Dateiinhalt nicht lesbar vorliegt, sage das transparent.
Wenn gefragt wird, wer dich erstellt hat: Der Schoepfer des Agents ist Sebastian Linges.
Gib kein HTML aus. Schreibe kurz, direkt, freundlich und natuerlich.`;
const agentPrompt = `Absender:
- Name: ${item.teams?.fromUser || ''}
- Anrede: ${item.teams?.salutation || 'Hallo'}
- Jobtitel: ${profile.jobTitle || ''}
- Abteilung: ${profile.department || ''}
- Standort: ${profile.officeLocation || ''}

Chat:
- Chat-ID: ${item.teams?.chatId || ''}
- Nachricht-ID: ${item.teams?.messageId || ''}
- Intent: ${item.control?.intent || 'request'}
- Sprache: ${item.language?.label || 'Deutsch'}

Nutzernachricht:
${item.body?.text || '(keine Textnachricht)'}

Attachments:
${attachmentLines}

Hosted Contents:
${hostedLines}

Links:
${linkLines}

Aufgabe:
Beantworte die aktuelle Nutzernachricht. Nutze Tools und Memory nur, wenn sie helfen. Liefere Text sowie relevante Bild-, Dokument- oder Linkinformationen, wenn etwas bereitsteht.`;
return [{ json: { ...item, systemMessage, agentPrompt } }];

const original = $('Build Agent Prompt').first().json;
const agent = $input.first().json || {};
let raw = agent.output ?? agent.text ?? agent.reply ?? agent.answer ?? agent.message ?? '';
if (agent.error || !String(raw || '').trim()) raw = original.replies?.fallback || 'Ich konnte die Anfrage gerade nicht vollstaendig verarbeiten.';
function stripMarkdown(text) {
  return String(text || '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^#{1,6}\s*/gm, '')
    .replace(/^\d+\.\s+/gm, '- ')
    .trim();
}
function escapeHtml(text) {
  return String(text || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function toTeamsHtml(text) {
  const lines = stripMarkdown(text).replace(/\r\n/g, '\n').replace(/\r/g, '\n').replace(/\n{3,}/g, '\n\n').split('\n');
  const html = [];
  let listOpen = false;
  let paragraph = [];
  const flushParagraph = () => { if (paragraph.length) { html.push(`<p>${paragraph.map(escapeHtml).join('<br>')}</p>`); paragraph = []; } };
  const closeList = () => { if (listOpen) { html.push('</ul>'); listOpen = false; } };
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) { flushParagraph(); closeList(); continue; }
    if (/^-\s+/.test(line)) { flushParagraph(); if (!listOpen) { html.push('<ul>'); listOpen = true; } html.push(`<li>${escapeHtml(line.replace(/^-\s+/, ''))}</li>`); continue; }
    closeList();
    paragraph.push(line);
  }
  flushParagraph();
  closeList();
  return `<div>${html.join('')}</div>`;
}
return [{ json: { chatId: original.teams.chatId, rawReply: String(raw).trim(), reply: toTeamsHtml(raw), usedFallback: Boolean(agent.error || !String(agent.output || agent.text || '').trim()) } }];
